\olsection{قواعد المكممات}

\subsection{قواعد $\lforall$}

\begin{defish}
\Axiom$ !A(t), \Gamma \fCenter \Delta$
\RightLabel{\LeftR{\lforall}}
\UnaryInf$ \lforall[x][!A(x)],\Gamma \fCenter \Delta$
\DisplayProof
\hfill
\Axiom$ \Gamma \fCenter \Delta, !A(a) $
\RightLabel{\RightR{\lforall}}
\UnaryInf$ \Gamma \fCenter \Delta, \lforall[x][!A(x)]$
\DisplayProof
\end{defish}

في~\LeftR{\lforall} يكون~$t$ حدًا مغلقًا (أي حدًا بلا متغيرات). وفي
\RightR{\lforall} يكون~$a$ !!a{constant} لا يجوز أن يرد في أي موضع
من التتابعية السفلى لقاعدة~\RightR{\lforall}. ونسمي~$a$
\emph{المتغير المميَّز} لاستدلال~\RightR{\forall}.\footnote{نستعمل
مصطلح «المتغير المميَّز» مع أن~$a$ في القاعدة أعلاه !!a{constant}؛
ولذلك أسباب تاريخية.}

\subsection{قواعد $\lexists$}

\begin{defish}
\Axiom$ !A(a), \Gamma \fCenter \Delta $
\RightLabel{\LeftR{\lexists}}
\UnaryInf$ \lexists[x][!A(x)], \Gamma \fCenter \Delta$
\DisplayProof
\hfill
\Axiom$ \Gamma \fCenter \Delta, !A(t) $
\RightLabel{\RightR{\lexists}}
\UnaryInf$ \Gamma \fCenter \Delta, \lexists[x][!A(x)]$
\DisplayProof
\end{defish}

مرة أخرى، يكون~$t$ حدًا مغلقًا، ويكون~$a$ !!a{constant} لا يرد في
التتابعية السفلى لقاعدة~\LeftR{\lexists}. ونسمي~$a$
\emph{المتغير المميَّز} لاستدلال~\LeftR{\lexists}.

يسمى الشرط القاضي بألا يرد المتغير المميَّز في التتابعية السفلى
لاستدلال~\RightR{\lforall} أو~\LeftR{\lexists}
\emph{شرط المتغير المميَّز}.

\begin{explain}
تذكّر الاصطلاح القائل إننا، حين تكون~$!A$ !!a{formula} يكون فيها
ال!!{variable}~$x$ حرًا، نشير إلى ذلك بكتابة~$!A(x)$. وفي السياق
نفسه تكون~$!A(t)$ اختصارًا لـ~$\Subst{!A}{t}{x}$. ولذلك كان يمكننا
أيضًا كتابة قاعدة~\RightR{\lexists} كما يأتي:
\begin{prooftree}
  \Axiom$\Gamma \fCenter \Delta, \Subst{!A}{t}{x}$
  \RightLabel{\RightR{\lexists}}
  \UnaryInf$\Gamma \fCenter \Delta, \lexists[x][!A]$
\end{prooftree}
لاحظ أن~$t$ قد يرد سلفًا في~$!A$؛ فقد تكون~$!A$، مثلًا،
$\Atom{\Obj P}{t,x}$. ومن ثم فإن استنتاج
$\Gamma \Sequent \Delta, \lexists[x][\Atom{\Obj P}{t,x}]$ من
~$\Gamma \Sequent \Delta, \Atom{\Obj P}{t,t}$ تطبيق صحيح
لـ~\RightR{\lexists}---إذ يجوز لك أن «تستبدل» ورودًا واحدًا أو أكثر
لـ~$t$ في المقدمة بال!!{variable} المربوط~$x$، ولا يلزم استبدالها
كلها. غير أن شرطي المتغير المميَّز في~\RightR{\lforall}
و~\LeftR{\lexists} يقتضيان ألا يرد ال!!{constant}~$a$ في~$!A$.
ولذلك لا يصح أن تستنتج
$\Gamma \Sequent \Delta, \lforall[x][\Atom{\Obj P}{a,x}]$ من
$\Gamma \Sequent \Delta, \Atom{\Obj P}{a,a}$ باستعمال
~$\RightR{\lforall}$.
\end{explain}

\begin{explain}
لا ترد أي قيود من جهة المتغير المميَّز على الحد~$t$ في~\RightR{\lexists}
و~\LeftR{\lforall}. أما في قاعدتي~\LeftR{\lexists}
و~\RightR{\lforall}، فيقتضي شرط المتغير المميَّز ألا يرد
ال!!{constant}~$a$ في أي موضع خارج~$!A(a)$ في التتابعية العليا.
وهذا ضروري لضمان سلامة النظام، أي إنه لا !!{derive}s إلا تتابعيات
صالحة. ومن دون هذا الشرط كان ما يأتي جائزًا:
\begin{prooftree}
  \Axiom$!A(a) \fCenter !A(a)$
  \RightLabel{*\LeftR{\lexists}}
  \UnaryInf$\lexists[x][!A(x)] \fCenter !A(a)$
  \RightLabel{\RightR{\lforall}}
  \UnaryInf$\lexists[x][!A(x)] \fCenter \lforall[x][!A(x)]$
  \DisplayProof\bottomAlignProof
  \qquad
  \Axiom$!A(a) \fCenter !A(a)$
  \RightLabel{*\RightR{\lforall}}
  \UnaryInf$!A(a) \fCenter \lforall[x][!A(x)]$
  \RightLabel{\LeftR{\lexists}}
  \UnaryInf$\lexists[x][!A(x)] \fCenter \lforall[x][!A(x)]$
\end{prooftree}
لكن التتابعية~$\lexists[x][!A(x)] \Sequent \lforall[x][!A(x)]$ ليست
صالحة.
\end{explain}

\end{document}

\olsection{قواعد المكممات}

\subsection{قواعد $\lforall$}

\begin{defish}
\Axiom$ !A(t), \Gamma \fCenter \Delta$
\RightLabel{\LeftR{\lforall}}
\UnaryInf$ \lforall[x][!A(x)],\Gamma \fCenter \Delta$
\DisplayProof
\hfill
\Axiom$ \Gamma \fCenter \Delta, !A(a) $
\RightLabel{\RightR{\lforall}}
\UnaryInf$ \Gamma \fCenter \Delta, \lforall[x][!A(x)]$
\DisplayProof
\end{defish}

أما~\LeftR{\lforall} فـ~$t$ فيها حد مغلق، أي خالٍ من المتغيرات. وأما
\RightR{\lforall} فـ~$a$ فيها !!a{constant}، وشرطه ألا يقع في شيء من التتابعية السفلى لقاعدة~\RightR{\lforall}.
ويسمى~$a$ \emph{المتغير المميَّز} لاستدلال~\RightR{\forall}.\footnote{إنما بقيت تسمية «المتغير المميَّز» لأسباب تاريخية، وإن كان~$a$ هنا !!a{constant}.}

\subsection{قواعد $\lexists$}

\begin{defish}
\Axiom$ !A(a), \Gamma \fCenter \Delta $
\RightLabel{\LeftR{\lexists}}
\UnaryInf$ \lexists[x][!A(x)], \Gamma \fCenter \Delta$
\DisplayProof
\hfill
\Axiom$ \Gamma \fCenter \Delta, !A(t) $
\RightLabel{\RightR{\lexists}}
\UnaryInf$ \Gamma \fCenter \Delta, \lexists[x][!A(x)]$
\DisplayProof
\end{defish}

وكذلك~$t$ هنا حد مغلق؛ وأما~$a$ فهو !!a{constant} لا يقع في التتابعية السفلى لقاعدة~\LeftR{\lexists}.
وهو، أعني~$a$، \emph{المتغير المميَّز} لاستدلال~\LeftR{\lexists}.

يسمى الشرط القاضي بألا يرد المتغير المميَّز في التتابعية السفلى
لاستدلال~\RightR{\lforall} أو~\LeftR{\lexists}
\emph{شرط المتغير المميَّز}.

\begin{explain}
إذا كانت~$!A$ !!a{formula} وفيها ال!!{variable}~$x$ حر، فاصطلاحنا أن نكتب~$!A(x)$.
وفي هذا السياق يدل~$!A(t)$ اختصارًا على~$\Subst{!A}{t}{x}$.
وعليه تصح كتابة قاعدة~\RightR{\lexists} بالصورة الآتية:
\begin{prooftree}
  \Axiom$\Gamma \fCenter \Delta, \Subst{!A}{t}{x}$
  \RightLabel{\RightR{\lexists}}
  \UnaryInf$\Gamma \fCenter \Delta, \lexists[x][!A]$
\end{prooftree}
لاحظ أن~$t$ قد يرد سلفًا في~$!A$؛ فقد تكون~$!A$، مثلًا،
$\Atom{\Obj P}{t,x}$. ومن ثم فإن استنتاج
$\Gamma \Sequent \Delta, \lexists[x][\Atom{\Obj P}{t,x}]$ من
~$\Gamma \Sequent \Delta, \Atom{\Obj P}{t,t}$ تطبيق صحيح
لـ~\RightR{\lexists}---إذ يجوز لك أن «تستبدل» ورودًا واحدًا أو أكثر
لـ~$t$ في المقدمة بال!!{variable} المربوط~$x$، ولا يلزم استبدالها
كلها. غير أن شرطي المتغير المميَّز في~\RightR{\lforall}
و~\LeftR{\lexists} يقتضيان ألا يرد ال!!{constant}~$a$ في~$!A$.
ولذلك لا يصح أن تستنتج
$\Gamma \Sequent \Delta, \lforall[x][\Atom{\Obj P}{a,x}]$ من
$\Gamma \Sequent \Delta, \Atom{\Obj P}{a,a}$ باستعمال
~$\RightR{\lforall}$.
\end{explain}

\begin{explain}
لا قيد على الحد~$t$ في~\RightR{\lexists}
و~\LeftR{\lforall} من جهة المتغير المميَّز. وأما~\LeftR{\lexists}
و~\RightR{\lforall} فشرطهما ألا يقع ال!!{constant}~$a$ في التتابعية العليا خارج~$!A(a)$.
ولا تستقيم سلامة النظام من غير هذا الشرط، أعني ألا !!{derive}s إلا التتابعيات الصالحة. إذ لو أُسقط لجاز ما يأتي:
\begin{prooftree}
  \Axiom$!A(a) \fCenter !A(a)$
  \RightLabel{*\LeftR{\lexists}}
  \UnaryInf$\lexists[x][!A(x)] \fCenter !A(a)$
  \RightLabel{\RightR{\lforall}}
  \UnaryInf$\lexists[x][!A(x)] \fCenter \lforall[x][!A(x)]$
  \DisplayProof\bottomAlignProof
  \qquad
  \Axiom$!A(a) \fCenter !A(a)$
  \RightLabel{*\RightR{\lforall}}
  \UnaryInf$!A(a) \fCenter \lforall[x][!A(x)]$
  \RightLabel{\LeftR{\lexists}}
  \UnaryInf$\lexists[x][!A(x)] \fCenter \lforall[x][!A(x)]$
\end{prooftree}
لكن التتابعية~$\lexists[x][!A(x)] \Sequent \lforall[x][!A(x)]$ ليست
صالحة.
\end{explain}

\end{document}

\olsection{قواعد المكممات}

\subsection{قواعد~$\lforall$}

\begin{defish}
\AxiomC{$!A(a)$}
\RightLabel{\Intro{\lforall}}
\UnaryInfC{$\lforall[x][\Atom{!A}{x}]$}
\DisplayProof
\hfill
\AxiomC{$\lforall[x][\Atom{!A}{x}]$}
\RightLabel{\Elim{\lforall}}
\UnaryInfC{$!A(t)$}
\DisplayProof
\end{defish}

في قاعدتي~$\lforall$، يكون~$t$ حدًا مغلقًا (أي حدًا لا يحتوي على أي
متغيرات)، ويكون~$a$ !!a{constant} لا يرد في النتيجة
$\lforall[x][!A(x)]$، ولا في أي افتراض !!{undischarged} في
ال!!{derivation} المنتهي بالمقدمة~$!A(a)$. ونسمي~$a$
\emph{المتغير المميَّز} لاستدلال~\Intro{\lforall}.
\footnote{نستعمل مصطلح ``المتغير المميَّز'' حتى وإن كان~$a$ في القاعدة
أعلاه رمزًا ثابتًا، وذلك لأسباب تاريخية.}

\subsection{قواعد~$\lexists$}

\begin{defish}
\AxiomC{$\Atom{!A}{t}$}
\RightLabel{\Intro{\lexists}}
\UnaryInfC{$\lexists[x][\Atom{!A}{x}]$}
\DisplayProof
\hfill
\AxiomC{$\lexists[x][\Atom{!A}{x}]$}
\AxiomC{[$\Atom{!A}{a}$]$^n$}
\DeduceC{$!C$}
\DischargeRule{\Elim{\lexists}}{n}
\BinaryInfC{$!C$}
\DisplayProof
\end{defish}

مرة أخرى، يكون~$t$ حدًا مغلقًا، ويكون~$a$ !!a{constant} لا يرد في
المقدمة~$\lexists[x][!A(x)]$، ولا في النتيجة~$!C$، ولا في أي افتراض
!!{undischarged} في ال!!{derivation}s المنتهية بالمقدمتين (عدا
الافتراضات~$!A(a)$). ونسمي~$a$ \emph{المتغير المميَّز} لاستدلال
\Elim{\lexists}.

يسمى الشرط القاضي بألا يرد المتغير المميَّز في النتائج ولا في أي
افتراض !!{undischarged} في ال!!{derivation}s المؤدية إلى مقدمات استدلال~\Intro{\lforall}
أو~\Elim{\lexists}، مع استثناء الافتراضات~$!A(a)$ التي تسقطها القاعدة الأخيرة، \emph{شرط المتغير المميَّز}.\footnote{تنبيه تصحيحي على الأصل: أُظهر استثناء الافتراضات المؤقتة التي تسقطها قاعدة حذف المكمّم الوجودي؛ فقد نصت عليه القاعدة المفصلة قبل هذا الملخص، وإغفاله يوسّع المنع خطأً.}

\begin{explain}
تذكّر الاصطلاح القائل إننا عندما تكون~$!A$ !!a{formula} يكون فيها
ال!!{variable}~$x$ حرًا، نشير إلى ذلك بكتابة~$!A(x)$. وفي السياق نفسه،
تكون~$!A(t)$ اختصارًا لـ~$\Subst{!A}{t}{x}$. ولذلك يمكننا أيضًا كتابة
قاعدة~$\Intro\lexists$ هكذا:
\begin{prooftree}
\AxiomC{$\Subst{!A}{t}{x}$}
\RightLabel{\Intro{\lexists}}
\UnaryInfC{$\lexists[x][!A]$}
\end{prooftree}
لاحظ أن~$t$ قد يرد أصلًا في~$!A$؛ فمثلًا قد تكون~$!A$ هي
$\Atom{\Obj P}{t,x}$. ومن ثم فإن استنتاج
$\lexists[x][\Atom{\Obj P}{t,x}]$ من~$\Atom{\Obj P}{t,t}$ تطبيق
صحيح لـ~$\Intro\lexists$---إذ يجوز لك أن ``تستبدل'' بموضع واحد أو
أكثر، وليس بالضرورة كل المواضع، للحد~$t$ في المقدمة ال!!{variable}
المقيد~$x$. غير أن شرطي المتغير المميَّز في~$\Intro\lforall$
و$\Elim\lexists$ يقتضيان ألا يرد ال!!{constant}~$a$ في~$!A$.
ولذلك لا يمكنك أن تستنتج على نحو صحيح
$\lforall[x][\Atom{\Obj P}{a,x}]$ من~$\Atom{\Obj P}{a,a}$ باستعمال
$\Intro\lforall$.
\end{explain}

\begin{explain}
لا توجد قيود من جهة المتغير المميَّز في~\Intro{\lexists} و\Elim{\lforall}، ويجوز اختيار
الحد المغلق~$t$ كيف اتفق. أما في قاعدتي
\Elim{\lexists} و\Intro{\lforall}، فيقتضي شرط المتغير المميَّز ألا
يرد ال!!{constant}~$a$ في أي موضع من النتيجة أو من افتراض
!!{undischarged}. والشرط ضروري لضمان سلامة النسق، أي إنه لا
!!{derive}s إلا !!{sentence}s تلزم عن الافتراضات ال!!{undischarged}
التي تشتق منها. ومن دون هذا الشرط، يكون الآتي جائزًا:
\begin{prooftree}
  \AxiomC{$\lexists[x][!A(x)]$}
  \AxiomC{$\Discharge{!A(a)}{1}$}
  \RightLabel{*\Intro{\lforall}}
  \UnaryInfC{$\lforall[x][!A(x)]$}
  \RightLabel{\Elim{\lexists}}
  \BinaryInfC{$\lforall[x][!A(x)]$}
\end{prooftree}
لكن~$\lexists[x][!A(x)] \Entails/ \lforall[x][!A(x)]$.

بما أن قواعد الحذف للمكممات لا تسمح إلا بإحلال حدود مغلقة محل
ال!!{variable}s، فإنه يلزم أن تكون أي !!{formula} يمكن اشتقاقها من
مجموعة من ال!!{sentence}s هي نفسها !!a{sentence}.
\end{explain}


\end{document}

\olsection{قواعد المكممات}

\subsection{قواعد~$\lforall$}

\begin{defish}
\AxiomC{$!A(a)$}
\RightLabel{\Intro{\lforall}}
\UnaryInfC{$\lforall[x][\Atom{!A}{x}]$}
\DisplayProof
\hfill
\AxiomC{$\lforall[x][\Atom{!A}{x}]$}
\RightLabel{\Elim{\lforall}}
\UnaryInfC{$!A(t)$}
\DisplayProof
\end{defish}

في قاعدتي~$\lforall$، الحد~$t$ مغلق، أي لا متغير فيه؛ و~$a$ هو
!!a{constant} لا يقع في النتيجة
$\lforall[x][!A(x)]$، ولا في فرض حاله !!{undischarged} ضمن
ال!!{derivation} المنتهي بـ~$!A(a)$.
ويسمى~$a$ \emph{المتغير المميَّز} لاستدلال~\Intro{\lforall}.
\footnote{بقيت تسمية «المتغير المميَّز» لأسباب تاريخية، وإن كان~$a$ في هذه القاعدة رمزًا ثابتًا.}

\subsection{قواعد~$\lexists$}

\begin{defish}
\AxiomC{$\Atom{!A}{t}$}
\RightLabel{\Intro{\lexists}}
\UnaryInfC{$\lexists[x][\Atom{!A}{x}]$}
\DisplayProof
\hfill
\AxiomC{$\lexists[x][\Atom{!A}{x}]$}
\AxiomC{[$\Atom{!A}{a}$]$^n$}
\DeduceC{$!C$}
\DischargeRule{\Elim{\lexists}}{n}
\BinaryInfC{$!C$}
\DisplayProof
\end{defish}

وكذلك~$t$ هنا حد مغلق. وأما~$a$ فهو !!a{constant} شرطه ألا يقع في
$\lexists[x][!A(x)]$، وهي المقدمة، ولا في النتيجة~$!C$، ولا في فرض
!!{undischarged} من ال!!{derivation}s المؤدية إلى المقدمتين، سوى فروض~$!A(a)$.
ويسمى~$a$ \emph{المتغير المميَّز} لاستدلال
\Elim{\lexists}.

هذا المنع لورود المتغير المميَّز في النتائج، أو في فرض
!!{undischarged} من ال!!{derivation}s المؤدية إلى مقدمات
\Intro{\lforall} أو~\Elim{\lexists}، مع استثناء الفروض التي يسقطها
حذف المكمّم الوجودي، يسمى \emph{شرط المتغير المميَّز}.

\textbf{تنبيه تصحيحي على الأصل.} أُظهر في هذا الملخص استثناء الفروض
المؤقتة التي تسقطها قاعدة حذف المكمّم الوجودي؛ فقد نصت عليه القاعدة المفصلة
قبله، وإسقاطه من الملخص يوسّع شرط المتغير المميز خطأً.

\begin{explain}
تذكّر الاصطلاح القائل إننا عندما تكون~$!A$ !!a{formula} يكون فيها
ال!!{variable}~$x$ حرًا، نشير إلى ذلك بكتابة~$!A(x)$. وفي السياق نفسه،
تكون~$!A(t)$ اختصارًا لـ~$\Subst{!A}{t}{x}$. ولذلك يمكننا أيضًا كتابة
قاعدة~$\Intro\lexists$ هكذا:
\begin{prooftree}
\AxiomC{$\Subst{!A}{t}{x}$}
\RightLabel{\Intro{\lexists}}
\UnaryInfC{$\lexists[x][!A]$}
\end{prooftree}
لاحظ أن~$t$ قد يرد أصلًا في~$!A$؛ فمثلًا قد تكون~$!A$ هي
$\Atom{\Obj P}{t,x}$. ومن ثم فإن استنتاج
$\lexists[x][\Atom{\Obj P}{t,x}]$ من~$\Atom{\Obj P}{t,t}$ تطبيق
صحيح لـ~$\Intro\lexists$---إذ يجوز لك أن ``تستبدل'' بموضع واحد أو
أكثر، وليس بالضرورة كل المواضع، للحد~$t$ في المقدمة ال!!{variable}
المقيد~$x$. غير أن شرطي المتغير المميَّز في~$\Intro\lforall$
و$\Elim\lexists$ يقتضيان ألا يرد ال!!{constant}~$a$ في~$!A$.
ولذلك لا يمكنك أن تستنتج على نحو صحيح
$\lforall[x][\Atom{\Obj P}{a,x}]$ من~$\Atom{\Obj P}{a,a}$ باستعمال
$\Intro\lforall$.
\end{explain}

\begin{explain}
أما~\Intro{\lexists} و\Elim{\lforall} فلا يلزمهما شرط المتغير المميَّز؛ ويجوز اختيار الحد المغلق~$t$ كيف اتفق.
وأما~\Elim{\lexists} و\Intro{\lforall} فشرطهما ألا يقع ال!!{constant}~$a$ في النتيجة أو في فرض
!!{undischarged}. وهذا شرط السلامة: فلا
!!{derive}s النظام إلا !!{sentence}s تلزم عن فروضه ال!!{undischarged}.
ولو سقط هذا الشرط لجاز الآتي:
\begin{prooftree}
  \AxiomC{$\lexists[x][!A(x)]$}
  \AxiomC{$\Discharge{!A(a)}{1}$}
  \RightLabel{*\Intro{\lforall}}
  \UnaryInfC{$\lforall[x][!A(x)]$}
  \RightLabel{\Elim{\lexists}}
  \BinaryInfC{$\lforall[x][!A(x)]$}
\end{prooftree}
لكن~$\lexists[x][!A(x)] \Entails/ \lforall[x][!A(x)]$.

بما أن قواعد الحذف للمكممات لا تسمح إلا بإحلال حدود مغلقة محل
ال!!{variable}s، فإنه يلزم أن تكون أي !!{formula} يمكن اشتقاقها من
مجموعة من ال!!{sentence}s هي نفسها !!a{sentence}.
\end{explain}


